import * as THREE from './vendor/three.module.js';
import {BastionModel} from './bastion-model.js?v=bastion-testing-123';
import {BastionState} from './bastion-state.js?v=bastion-testing-123';
import {BastionProjectiles} from './bastion-projectiles.js?v=bastion-testing-123';
import {BastionEffects} from './bastion-effects.js?v=bastion-testing-123';
import {angleDistance} from './bastion-geometry.js?v=bastion-testing-123';
import {traceImpact} from './combat-collision.js?v=robot-experiments-108';
export class Bastion {
 constructor(scene,damage,config,{onEvent=()=>{},onPlayerHit=()=>{},onWindup=()=>{}}={}){Object.assign(this,{scene,damage,config,onEvent,onPlayerHit,onWindup});this.model=new BastionModel(scene,config);this.root=this.model.root;this.state=new BastionState(config);this.evac=true;this.projectiles=null;this.waves=[];this.stunRemaining=0;this.feedback='';this.hitCooldown=0;this.reset();this.effects=new BastionEffects(this);this.projectiles=new BastionProjectiles(this);}
 get sections(){return this.model.sections;}
 get dead(){return this.state.phase==='defeated';}
 get coreOpen(){return this.state.exposed&&this.stunRemaining<=0;}
 aimPoint(){return this.model.corePoint(this.state.coreIndex);}
 reset(seed=this.config.seed){this.state.reset(seed);this.model.reset();this.damage.units=this.damage.units.filter(u=>u.entity!==this);this.combatUnit=this.damage.add('bastion','robot',this,this.config.core.health);this.player=null;this.attackKey='';this.stunRemaining=0;this.hitCooldown=0;this.feedback='';this.waves=[];this.projectiles?.reset();this.effects?.reset();this.sync();}
 sync(){this.combatUnit.shapes=this.dead?[]:this.model.shapes(this.state);}
 applyHit(hit,power,key='strike'){if(hit?.orb){if(this.config.deflect.enabled&&this.coreOpen)this.projectiles?.deflect(hit.orb,this.aimPoint());else this.projectiles?.remove(hit.orb);return 0;}if(hit?.unit!==this.combatUnit)return 0;this.attackKey=String(key);const result=this.damage.hurt(this.combatUnit,power,hit.point,hit.part);this.sync();return result;}
 modifyDamage(power,point,part){if(part?.startsWith('launcher-')){const i=Number(part.split('-')[1]),dealt=this.state.hurtLauncher(i,power),l=this.state.launchers[i];if(dealt){this.feedback=l.destroyed?'LAUNCHER DESTROYED':'LAUNCHER HIT';this.effects?.impact(point,'#ffb151');if(l.destroyed){for(const s of this.sections)if(s.node===this.model.launchers[i])s.hidden=s.collisionDisabled=true;this.model.launchers[i].visible=false;this.onEvent('Launcher '+(i+1)+' destroyed · fewer shots next barrage.');}}else this.feedback='LAUNCHERS ARMOURED DURING BARRAGE';return 0;}
  if(part==='core'&&this.coreOpen){this.feedback='CORE STRIKE';this.effects?.impact(point,'#6ffff0');return power*this.config.core.damageMultiplier*this.state.multiplier(this.attackKey);}this.feedback=this.coreOpen?'HIT THE GLOWING CORE':'CORE ARMOURED';return 0;}
 interrupt(seconds=1){if(this.dead)return false;this.stunRemaining=Math.max(this.stunRemaining,seconds);this.onEvent('Bastion interrupted · armour locked briefly.');return true;}
 defeat(){this.state.defeat();this.projectiles?.reset();this.waves=[];this.effects?.impact(this.root.position.clone().add(new THREE.Vector3(0,25,0)),'#baffed',8);this.onEvent('BASTION DEFEATED · Reset to replay this seed.');}
 addWave(id){const core=this.config.core.locations[this.state.coreIndex].position;this.waves.push({id,age:0,angle:Math.atan2(core[0],core[2])});}
 checkWaves(player,previous){if(this.dead||player.phased)return;const c=this.config.pulse,body=this.onBody(player),current=this.root.worldToLocal(new THREE.Vector3().copy(player.position)),last=this.root.worldToLocal(new THREE.Vector3().copy(previous));for(const w of this.waves){for(let i=0;i<=c.sweepSamples;i++){const point=last.clone().lerp(current,i/c.sweepSamples),radius=Math.hypot(point.x,point.z),angle=Math.atan2(point.x,point.z),gap=angleDistance(angle,w.angle)<c.gapHalfAngle,surface=body&&point.y*this.config.body.height/40<=w.age*c.surfaceSpeed+c.surfaceWidth/2&&point.y*this.config.body.height/40>=w.age*c.surfaceSpeed-c.surfaceWidth/2-c.surfaceSpeed*c.linger,ground=point.y<=c.groundHitHeight&&radius<=Math.min(c.maxRadius,w.age*c.groundSpeed+c.groundWidth/2)&&radius>=w.age*c.groundSpeed-c.groundWidth/2-c.groundSpeed*c.linger;if(!(surface||ground))continue;if(gap){if((body||!c.gapRequiresBody)&&this.state.awardGap())this.onEvent('PULSE GAP THREADED · core window extended.');}else this.playerHit(player.position,c.damage);}}}
 safePaths(){const p=this.config.core.locations[this.state.coreIndex].position,sign=Math.sign(p[2]),height=this.config.projectiles.collisionHeight,wall=Math.abs(p[2])+height,near=[p[0],height+.08,sign*wall],l=Math.hypot(p[0],p[2]),far=[p[0]/l*this.config.barrage.safeStartRadius,height+.08,p[2]/l*this.config.barrage.safeStartRadius];return{safe:[far,near,[p[0],p[1],sign*wall]],greedy:[[-p[0],this.config.barrage.greedyEntryHeight,sign*wall],[-p[0],p[1],sign*wall],[p[0],p[1],sign*wall]]};}
 routeAt(position){const p=this.root.worldToLocal(new THREE.Vector3().copy(position));return(p.z>=0?'front-':'back-')+(p.x<0?'left':'right');}
 onBody(player){return player.motion?.support?.building==='bastion'&&player.motion.mode!=='air'||!!traceImpact(player.position,player.position,{sections:this.sections,ground:false,radius:this.config.traversal.surfaceContactRadius});}
 updateWorld(dt,time,player){this.player=player;this.hitCooldown=Math.max(0,this.hitCooldown-dt);this.model.animate(dt,time,player.position,this.dead||(this.config.body.pauseTurnAtGroundContact&&player.motion?.mode==='ground'&&this.onBody(player)));const wasStunned=this.stunRemaining>0;this.stunRemaining=Math.max(0,this.stunRemaining-dt);if(!wasStunned){const events=this.state.step(dt);for(const e of events){if(e.type==='windup'){this.onEvent('PULSE CHARGING · Leave the body, or thread the cyan gap.');this.onWindup();}if(e.type==='wave')this.addWave?.(e.id);if(e.type==='barrage'){this.onEvent('CORE EXPOSED · '+this.state.patterns.join(' + '));this.projectiles?.beginBarrage();}}}for(const w of this.waves)w.age+=dt;const p=this.config.pulse;this.waves=this.waves.filter(w=>w.age<Math.max(p.maxRadius/p.groundSpeed,this.config.body.height/p.surfaceSpeed)+p.linger+p.groundWidth/p.groundSpeed);this.projectiles?.update(wasStunned?0:dt,time,player);this.effects?.update(dt,time);this.paint(time);this.sync();}
 afterPlayer(dt,player,previous){this.player=player;const attached=this.onBody(player);this.state.trackRoute(attached?this.routeAt(player.position):null,dt);this.checkWaves?.(player,previous);this.projectiles?.checkPlayer(player,previous);this.model.capture(player.motion);}
 playerHit(point,power){if(this.hitCooldown>0||this.player?.phased||this.dead)return;this.hitCooldown=this.config.pulse.hitInterval;this.state.hitsTaken++;this.state.damageTaken+=power;this.onPlayerHit(point,power);}
 trace(a,b,radius=0,{sectionsOnly=false}={}){if(sectionsOnly)return traceImpact(a,b,{sections:this.sections,ground:false,radius});let hit=traceImpact(a,b,{targets:this.combatUnit.alive?[this.combatUnit]:[],ground:false,radius});const orb=this.projectiles?.trace(a,b,radius);if(orb&&(!hit||orb.t<hit.t))hit=orb;return hit;}
 paint(time){for(const {id,patch} of this.model.routePatches)patch.visible=id===this.state.markedRoute;for(const p of this.model.plates){const active=p.index===this.state.coreIndex;p.core.visible=active&&this.coreOpen;p.plate.visible=!(active&&this.coreOpen);p.material.emissive.set(active&&['windup','pulse'].includes(this.state.phase)?'#ff9c31':'#102c35');p.material.emissiveIntensity=active&&this.state.phase==='windup'?1+Math.sin(time*18)**2*3:.4;}
  for(const p of this.model.parts){let marked=false;if(this.state.markedRoute){const left=this.state.markedRoute.includes('left');marked=p.id.includes(left?'left-':'right-');}p.material.emissive.set(marked?this.config.routes.warningColor:'#000000');p.material.emissiveIntensity=marked?.8:0;}}
 diagnostics(){return{...this.state.diagnostics(),health:this.combatUnit.health,maxHealth:this.combatUnit.maxHealth,coreOpen:this.coreOpen,stunned:this.stunRemaining,feedback:this.feedback,projectiles:this.projectiles?.diagnostics()||{},bodyHeight:this.config.body.height};}
}
